<?php
/** @var array $lots */ /** @var array $warehouses */ /** @var array $totals */ /** @var array $filters */
?>
<div class="flex flex-wrap justify-between items-center gap-3 mb-4"><div><p class="text-sm text-gray-600">Lot-level stock across every warehouse. Adjustments are made from the product editor so each movement retains its traceability context.</p></div><div class="flex gap-2"><a class="vp-btn vp-btn-secondary" href="<?= base_url('admin/warehouses') ?>"><i class="ri-building-2-line"></i> Warehouses</a><a class="vp-btn vp-btn-secondary" href="<?= base_url('admin/products') ?>"><i class="ri-box-3-line"></i> Products</a></div></div>
<div class="grid md:grid-cols-4 gap-3 mb-5"><?php foreach ($totals as $total): ?><div class="vp-card vp-card-pad"><div class="text-xs text-gray-500"><?= vp_safe_html($total['code']) ?><?= !empty($total['isAogHub']) ? ' · AOG' : '' ?></div><div class="font-bold"><?= vp_safe_html($total['name']) ?></div><div class="mt-2 text-2xl font-extrabold"><?= (int) $total['available'] ?></div><div class="text-xs text-gray-500">available · <?= (int) $total['lotCount'] ?> lots<?= (int) $total['expiringCount'] ? ' · ' . (int) $total['expiringCount'] . ' expiring' : '' ?></div></div><?php endforeach; ?></div>
<form method="get" class="vp-card vp-card-pad grid md:grid-cols-4 gap-3 mb-5"><input class="vp-input" name="q" value="<?= vp_safe_html($filters['q']) ?>" placeholder="Product, SKU, lot or serial"><select class="vp-select" name="warehouse"><option value="">All warehouses</option><?php foreach ($warehouses as $warehouse): ?><option value="<?= $warehouse['id'] ?>" <?= $filters['warehouseId'] === $warehouse['id'] ? 'selected' : '' ?>><?= vp_safe_html($warehouse['code'] . ' — ' . $warehouse['name']) ?></option><?php endforeach; ?></select><select class="vp-select" name="status"><option value="">All statuses</option><?php foreach (['ACTIVE','QUARANTINE','EXPIRED','DEPLETED'] as $status): ?><option value="<?= $status ?>" <?= $filters['status'] === $status ? 'selected' : '' ?>><?= $status ?></option><?php endforeach; ?></select><button class="vp-btn vp-btn-primary justify-center" type="submit">Filter inventory</button></form>
<div class="overflow-x-auto"><table class="vp-admin-table text-xs"><thead><tr><th>Product</th><th>Warehouse</th><th>Lot / serial</th><th>On hand</th><th>Reserved</th><th>Available</th><th>Expiry</th><th>Status</th><th>Transfer</th></tr></thead><tbody><?php if (empty($lots)): ?><tr><td colspan="9" class="text-center text-gray-500">No inventory lots match this filter.</td></tr><?php else: foreach ($lots as $lot): [$statusLabel, $statusClass] = vp_inventory_lot_status_label($lot['status']); [$expiryLabel, $expiryClass] = vp_inventory_expiry_label($lot['expiresAt'] ?? null); ?><tr><td><a class="font-semibold text-brand-600 hover:underline" href="<?= base_url('admin/products/edit/' . $lot['productId']) ?>"><?= vp_safe_html($lot['productName']) ?></a><div class="font-mono text-gray-500"><?= vp_safe_html($lot['productSku']) ?></div></td><td><b><?= vp_safe_html($lot['warehouseCode']) ?></b><?php if (!empty($lot['isAogHub'])): ?> <span class="text-amber-700">AOG</span><?php endif; ?></td><td><b><?= vp_safe_html($lot['lotNumber']) ?></b><?php if (!empty($lot['serialNumber'])): ?><br>S/N <?= vp_safe_html($lot['serialNumber']) ?><?php endif; ?></td><td><?= (int) $lot['quantityOnHand'] ?></td><td><?= (int) $lot['quantityReserved'] ?></td><td><b><?= (int) $lot['quantityAvailable'] ?></b></td><td class="<?= $expiryClass ?>"><?= vp_safe_html($expiryLabel) ?></td><td><span class="vp-pill <?= $statusClass ?>"><?= vp_safe_html($statusLabel) ?></span></td><td><?php if ($lot['status'] === 'ACTIVE' && (int) $lot['quantityAvailable'] > 0): ?><details><summary class="cursor-pointer text-brand-600">Move</summary><form method="post" action="<?= base_url('admin/inventory/transfer/' . $lot['id']) ?>" class="mt-2 space-y-1 min-w-44"><input type="hidden" name="<?= $csrf_token_name ?>" value="<?= $csrf_token ?>"><select class="vp-select" name="targetWarehouseId" required><option value="">To warehouse…</option><?php foreach ($warehouses as $warehouse): if ($warehouse['id'] !== $lot['warehouseId']): ?><option value="<?= $warehouse['id'] ?>"><?= vp_safe_html($warehouse['code']) ?></option><?php endif; endforeach; ?></select><input class="vp-input" name="quantity" type="number" min="1" max="<?= (int) $lot['quantityAvailable'] ?>" placeholder="Qty" required><input class="vp-input" name="note" maxlength="500" placeholder="Transfer reference"><button class="vp-btn vp-btn-secondary vp-btn-sm" type="submit">Transfer</button></form></details><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div>
